//! GraphQL commands/scalar projections and the authorized company/ticket
//! read adapters. GraphQL types are generated by the running backend, so
//! commands and scalar projections use a small JSON client rather than
//! build-time schema generation.

use crate::config::GRAPHQL_URL;
use serde_json::Value;

pub async fn graphql(token: &str, query: &str) -> Result<Value, String> {
    let body = serde_json::json!({ "query": query }).to_string();
    let response = gloo_net::http::Request::post(GRAPHQL_URL)
        .header("authorization", &format!("Bearer {token}"))
        .header("content-type", "application/json")
        .body(body)
        .map_err(|e| e.to_string())?
        .send()
        .await
        .map_err(|e| format!("network error talking to {GRAPHQL_URL}: {e}"))?;

    if response.status() == 401 {
        crate::auth::session_expired();
        return Err("your session expired - sign in again".into());
    }
    let json: Value = response
        .json()
        .await
        .map_err(|e| format!("couldn't decode the response as JSON: {e}"))?;

    if let Some(errors) = json.get("errors") {
        return Err(format!("GraphQL returned errors: {errors}"));
    }
    Ok(json)
}

/// `submitCommand(boundedContext, commandTypeName, payload)` -
/// `payload` is a raw JSON *string* argument (see `skilj-graphql`'s own
/// `submit_command_field` doc comment - a wire-shape choice on skilj's
/// side, not this app's), so this double-encodes it the same way
/// `tests/support/mod.rs::submit_command_mutation` does on the backend's
/// own test side.
pub async fn submit_command(
    token: &str,
    bounded_context: &str,
    command_type_name: &str,
    payload: &Value,
) -> Result<Value, String> {
    let payload_json = serde_json::to_string(payload).map_err(|e| e.to_string())?;
    let payload_literal = serde_json::to_string(&payload_json).map_err(|e| e.to_string())?;
    let query = format!(
        "mutation {{ submitCommand(boundedContext: {bounded_context:?}, commandTypeName: {command_type_name:?}, payload: {payload_literal}) {{ accepted rejectionReason rejectionKind triggeredEventSequences }} }}"
    );
    let response = graphql(token, &query).await?;
    let result = &response["data"]["submitCommand"];
    if result["accepted"].as_bool() == Some(true) {
        Ok(result.clone())
    } else {
        Err(result["rejectionReason"]
            .as_str()
            .unwrap_or("rejected, no reason given")
            .to_string())
    }
}

/// The highest sequence an accepted `submit_command` result says its
/// command produced - what `query_projection_after` waits for.
pub fn last_triggered_sequence(result: &Value) -> Option<i64> {
    result["triggeredEventSequences"]
        .as_array()?
        .iter()
        .filter_map(Value::as_i64)
        .max()
}

/// `projection(boundedContext, name, key)` - the result comes back as
/// an opaque, JSON-encoded *string* rather than a typed object (found
/// while wiring this up: `schemars`-derived shapes like the enum/map
/// fields these projections use don't match what `skilj-graphql`'s
/// mapper recognises as a scalar - its own documented fallback, not a
/// bug to work around here), so this parses it a second time.
pub async fn query_projection(
    token: &str,
    bounded_context: &str,
    name: &str,
    key: &str,
    graphql_type: &str,
    field: &str,
) -> Result<Value, String> {
    query_projection_after(token, bounded_context, name, key, graphql_type, field, None).await
}

/// `query_projection`, but for an async projection read right after this
/// session's own write: with `wait_for_sequence`, skilj holds the answer
/// until the projection has folded that sequence (`waitForSequence`), or
/// refuses once its `projection_query_wait_timeout` runs out.
pub async fn query_projection_after(
    token: &str,
    bounded_context: &str,
    name: &str,
    key: &str,
    graphql_type: &str,
    field: &str,
    wait_for_sequence: Option<i64>,
) -> Result<Value, String> {
    let wait = wait_for_sequence
        .map(|seq| format!(", waitForSequence: {seq}"))
        .unwrap_or_default();
    let query = format!(
        "query {{ projection(boundedContext: {bounded_context:?}, name: {name:?}, key: {key:?}{wait}) {{ ... on {graphql_type} {{ {field} }} }} }}"
    );
    let response = graphql(token, &query).await?;
    let raw = response["data"]["projection"][field]
        .as_str()
        .ok_or_else(|| format!("no {field:?} field in the projection response: {response}"))?;
    serde_json::from_str(raw).map_err(|e| format!("couldn't parse the projection's own JSON: {e}"))
}

/// `projection(...)` for a projection whose fields are all plain scalars
/// (`MarketingSignals`, `CompanyEngagement`): those come back typed, not
/// as the JSON-encoded string `query_projection` unwraps, so this returns
/// the projection object itself, with GraphQL's camelCase field names.
/// `wait_for_sequence` as in `query_projection_after`.
pub async fn query_projection_fields(
    token: &str,
    bounded_context: &str,
    name: &str,
    key: &str,
    fields: &str,
    wait_for_sequence: Option<i64>,
) -> Result<Value, String> {
    let wait = wait_for_sequence
        .map(|seq| format!(", waitForSequence: {seq}"))
        .unwrap_or_default();
    let query = format!(
        "query {{ projection(boundedContext: {bounded_context:?}, name: {name:?}, key: {key:?}{wait}) {{ ... on {bounded_context}_{name} {{ {fields} }} }} }}"
    );
    let response = graphql(token, &query).await?;
    Ok(response["data"]["projection"].clone())
}

#[derive(Clone, Debug, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CompanyAccess {
    pub company_id: String,
    pub bounded_context: String,
}

pub async fn companies(token: &str) -> Result<Vec<CompanyAccess>, String> {
    let url = GRAPHQL_URL.replace("/graphql", "/v1/helpdesk/companies");
    let response = gloo_net::http::Request::get(&url)
        .header("authorization", &format!("Bearer {token}"))
        .send()
        .await
        .map_err(|e| e.to_string())?;
    if response.status() == 401 {
        crate::auth::session_expired();
    }
    if !response.ok() {
        return Err("couldn't discover authorized companies".into());
    }
    response.json().await.map_err(|e| e.to_string())
}

#[derive(Clone, Debug, Default, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TicketPage {
    pub tickets: std::collections::HashMap<String, crate::model::TicketQueueEntry>,
    pub contents: std::collections::HashMap<String, crate::model::CustomerTicketContent>,
    pub has_more: bool,
}

pub async fn ticket_page(
    token: &str,
    company_id: &str,
    offset: usize,
    wait_for_sequence: Option<i64>,
    details: &std::collections::HashMap<String, usize>,
    abort: &web_sys::AbortSignal,
) -> Result<TicketPage, String> {
    let url = GRAPHQL_URL.replace("/graphql", "/v1/helpdesk/tickets");
    let response = gloo_net::http::Request::post(&url)
        .abort_signal(Some(abort))
        .header("authorization", &format!("Bearer {token}"))
        .json(&serde_json::json!({ "companyId": company_id, "offset": offset, "waitForSequence": wait_for_sequence, "details": details }))
        .map_err(|e| e.to_string())?.send().await.map_err(|e| e.to_string())?;
    if response.status() == 401 {
        crate::auth::session_expired();
    }
    if !response.ok() {
        return Err(response
            .text()
            .await
            .unwrap_or_else(|_| "couldn't load tickets".into()));
    }
    response.json().await.map_err(|e| e.to_string())
}
